changeSet.sql:
DECLARE
  engine_table_count NUMBER;
  matching_count NUMBER;
  resolved_id VARCHAR2(128);
  resolved_key VARCHAR2(255);
  resolved_version NUMBER;
  resolved_tenant VARCHAR2(64);
BEGIN
  SELECT COUNT(*) INTO engine_table_count
  FROM USER_TABLES
  WHERE TABLE_NAME = 'ACT_RE_PROCDEF';

  IF engine_table_count = 1 THEN
    FOR release_row IN (
      SELECT ID_, CASE_DEF_KEY_, TENANT_ID_, ENGINE_DEPLOYMENT_ID_
      FROM CM_CASE_DEF_RELEASE
      WHERE KIND_ = 'ORCHESTRATION'
        AND STATUS_ = 'ACTIVE'
        AND ENGINE_DEPLOYMENT_ID_ IS NOT NULL
    ) LOOP
      EXECUTE IMMEDIATE
        'SELECT COUNT(*), MIN(ID_), MIN(KEY_), MIN(VERSION_), MIN(TENANT_ID_) ' ||
        'FROM ACT_RE_PROCDEF ' ||
        'WHERE DEPLOYMENT_ID_ = :deployment_id AND KEY_ = :definition_key ' ||
        'AND (TENANT_ID_ = :tenant_id OR (:tenant_id_null IS NULL AND TENANT_ID_ IS NULL))'
        INTO matching_count, resolved_id, resolved_key, resolved_version, resolved_tenant
        USING release_row.ENGINE_DEPLOYMENT_ID_, release_row.CASE_DEF_KEY_,
              release_row.TENANT_ID_, release_row.TENANT_ID_;

      IF matching_count = 1 THEN
        UPDATE CM_CASE_DEF_RELEASE
        SET ENGINE_PROC_DEF_ID_ = resolved_id,
            ENGINE_PROC_DEF_KEY_ = resolved_key,
            ENGINE_PROC_DEF_VER_ = resolved_version,
            ENGINE_TENANT_ID_ = resolved_tenant,
            VALIDATED_AT_ = COALESCE(VALIDATED_AT_, PUBLISHED_AT_)
        WHERE ID_ = release_row.ID_;
      END IF;
    END LOOP;
  END IF;
END;

CREATE OR REPLACE TRIGGER TRG_CM_CDB_AUTHORITY
BEFORE INSERT OR UPDATE OF CASE_DEF_ID_, CASE_DEF_KEY_, TENANT_ID_
ON CM_CASE_DEF_BINDING
FOR EACH ROW
DECLARE
  authoritative_key CM_CASE_DEF.KEY_%TYPE;
  authoritative_tenant CM_CASE_DEF.TENANT_ID_%TYPE;
BEGIN
  SELECT definition.KEY_, definition.TENANT_ID_
  INTO authoritative_key, authoritative_tenant
  FROM CM_CASE_DEF definition
  WHERE definition.ID_ = :NEW.CASE_DEF_ID_;

  IF :NEW.CASE_DEF_KEY_ IS NULL THEN
    :NEW.CASE_DEF_KEY_ := authoritative_key;
  END IF;
  IF :NEW.TENANT_ID_ IS NULL THEN
    :NEW.TENANT_ID_ := authoritative_tenant;
  END IF;

  IF :NEW.CASE_DEF_KEY_ != authoritative_key
    OR (:NEW.TENANT_ID_ IS NULL AND authoritative_tenant IS NOT NULL)
    OR (:NEW.TENANT_ID_ IS NOT NULL AND authoritative_tenant IS NULL)
    OR :NEW.TENANT_ID_ != authoritative_tenant THEN
    RAISE_APPLICATION_ERROR(-20001,
      'Binding key/tenant must match its immutable case definition');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RAISE_APPLICATION_ERROR(-20001,
      'Binding key/tenant must match its immutable case definition');
END;
